blogs.forEach(blog => {
  const blogCanonical = `${SITE_URL}/blog/${blog.slug}`;
  const blogDesc = blog.metaDescription || blog.excerpt || blog.description || `${blog.title} - Expert NDT insights from ASNT Level III professionals at Atlantis NDT.`;
  const isoDate = blog.createdAt || blog.date || '2026-01-01';
  const isoModified = blog.updatedAt || isoDate;

  // Article structured data for pre-rendered HTML (critical for Googlebot)
  const blogStructuredData = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "TechArticle",
        "headline": blog.title,
        "description": blogDesc,
        "datePublished": isoDate,
        "dateModified": isoModified,
        "author": { "@type": "Organization", "name": "Atlantis NDT", "url": SITE_URL },
        "publisher": {
          "@type": "Organization",
          "name": "Atlantis NDT",
          "logo": { "@type": "ImageObject", "url": `${SITE_URL}/favicon-96x96.jpg`, "width": 96, "height": 96 }
        },
        "mainEntityOfPage": { "@type": "WebPage", "@id": blogCanonical },
        "image": `${SITE_URL}/og-image.jpg`,
        "inLanguage": "en-US",
        "isAccessibleForFree": true
      },
      {
        "@type": "BreadcrumbList",
        "itemListElement": [
          { "@type": "ListItem", "position": 1, "name": "Home", "item": SITE_URL },
          { "@type": "ListItem", "position": 2, "name": "Blog", "item": `${SITE_URL}/blog` },
          { "@type": "ListItem", "position": 3, "name": blog.title, "item": blogCanonical }
        ]
      }
    ]
  };

  // Round-3 critical fix: inject FULL blog.content into the static HTML so
  // Google sees the substantive 800-2,000w article body — not just a 13-word
  // title+snippet shell. The React BlogDetail page still hydrates on top of
  // this server-rendered body for client interactivity.
  const blogContentHtml = (blog.content || '')
    .replace(/<!DOCTYPE[^>]*>/gi, '')
    .replace(/<\/?html[^>]*>/gi, '')
    .replace(/<\/?head[^>]*>/gi, '')
    .replace(/<\/?body[^>]*>/gi, '');
  const fullBody = `  <header><nav aria-label="Main Navigation"><a href="/">Home</a><a href="/blog">Blog</a><a href="/contact">Free Consultation</a></nav></header>
  <main>
    <article>
      <h1>${blog.title}</h1>
      <p class="snippet">${blog.snippet || blog.excerpt || ''}</p>
      <div class="meta">
        <span>By Anoop Rayavarapu, ASNT NDT Level III</span> ·
        <time datetime="${isoDate}">${blog.date || isoDate}</time>
        ${blog.category ? ` · <span class="category">${blog.category}</span>` : ''}
      </div>
      <div class="blog-content">
${blogContentHtml}
      </div>
      <nav class="post-footer" aria-label="Related Atlantis NDT pages">
        <a href="/consulting/asnt-level-iii-consulting-services">ASNT Level III consulting</a> ·
        <a href="/atlantis-academy">Atlantis NDT Academy</a> ·
        <a href="/erp">Atlantis NDT ERP</a> ·
        <a href="/digital-twins">Digital Twin platform</a> ·
        <a href="/best-ndt-reporting-software-2026">Reporting Software</a> ·
        <a href="/contact">Free consultation</a>
      </nav>
${blogIntentBlock(blog)}
      <section class="products-services" aria-label="Atlantis NDT products and services">
        <h2>Atlantis NDT Products &amp; Services</h2>
        <p>Atlantis NDT pairs field expertise with software: <a href="/erp">NDT inspection management software — Atlantis ERP</a> (certification tracking, work orders, method-specific reporting on every business app you need), a <a href="/digital-twins">digital twin platform for asset integrity</a> (3D corrosion mapping, API 581 RBI, API 579 FFS), and <a href="/best-ndt-reporting-software-2026">NDT reporting software</a>. Build your team with <a href="/training">NDT training &amp; certification</a> (ASNT, API 510/570/653 — 96% first-attempt pass rate) and <a href="/asnt-certification">ASNT certification pathways</a>, or bring in <a href="/consulting">ASNT Level III consulting</a> for RBI, FFS, and written practices. Capture as-built reality with <a href="/3d-scanning-services">3D laser scanning services</a>. Affordable, accessible, fully customizable — <a href="/contact">book a free consultation</a>.</p>
      </section>
    </article>
  </main>`;

  routes.push({
    path: `/blog/${blog.slug}`,
    title: `${blog.title} | Atlantis NDT`,
    description: blogDesc,
    canonical: blogCanonical,
    structuredData: blogStructuredData,
    bodyContent: fullBody,
  });
});

